<style>
.customer-workspace{--cc-bg:#fff;--cc-soft:#f1f5f9;--cc-text:#0f172a;--cc-muted:#475569;--cc-line:#cbd5e1;--cc-brand:#0e7490;--cc-info:#155e75;--cc-info-bg:#ecfeff;--cc-good:#065f46;--cc-good-bg:#ecfdf5;--cc-bad:#9f1239;--cc-bad-bg:#fff1f2;--cc-warn:#92400e;--cc-warn-bg:#fffbeb;color:var(--cc-text)}.dark .customer-workspace{--cc-bg:#151e30;--cc-soft:#202c40;--cc-text:#edf2f7;--cc-muted:#b8c5d6;--cc-line:#41516a;--cc-brand:#67e8f9;--cc-info:#bae6fd;--cc-info-bg:#123444;--cc-good:#bbf7d0;--cc-good-bg:#12382c;--cc-bad:#fecdd3;--cc-bad-bg:#3d202e;--cc-warn:#fde68a;--cc-warn-bg:#3c301b}.cc-icon{height:18px;width:18px;flex-shrink:0;display:inline-block;vertical-align:middle}.cc-form-wrap{max-width:960px;margin:auto}.cc-head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;margin-bottom:20px}.cc-title{font-size:25px;line-height:1.35;font-weight:800;color:var(--cc-text)}.cc-subtitle{font-size:12px;line-height:1.7;color:var(--cc-muted);margin-top:6px}.cc-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid var(--cc-line);background:var(--cc-bg);color:var(--cc-text);padding:11px 15px;border-radius:11px;font-size:12px;font-weight:700;cursor:pointer}.cc-btn:hover{background:var(--cc-soft)}.cc-primary{background:#0e7490!important;color:#fff!important;border-color:#0e7490!important}.cc-primary:hover{background:#155e75!important}.cc-btn:disabled{opacity:.5;cursor:not-allowed}.cc-btn:focus-visible{outline:3px solid #22d3ee;outline-offset:2px}.cc-section{padding:22px;border:1px solid var(--cc-line);border-radius:17px;background:var(--cc-bg);margin-bottom:18px}.cc-section h2{display:flex;align-items:center;gap:9px;font-size:14px;font-weight:750;margin:0 0 7px;color:var(--cc-text)}.cc-section h2 .cc-icon{color:var(--cc-brand)}.cc-section>p{font-size:11px;line-height:1.7;color:var(--cc-muted);margin-bottom:16px}.cc-field-grid{display:grid;grid-template-columns:1fr 1fr;gap:17px}.cc-note{display:flex;align-items:flex-start;gap:9px;padding:13px 15px;border-radius:12px;background:var(--cc-info-bg);color:var(--cc-info);border:1px solid var(--cc-line);font-size:12px;line-height:1.7;margin-bottom:18px}.cc-note[data-tone=bad]{background:var(--cc-bad-bg);color:var(--cc-bad)}.cc-note[data-tone=warn]{background:var(--cc-warn-bg);color:var(--cc-warn)}.cc-note[data-tone=good]{background:var(--cc-good-bg);color:var(--cc-good)}.cc-editor input,.cc-editor select,.cc-editor textarea{color-scheme:light}.dark .cc-editor input,.dark .cc-editor select,.dark .cc-editor textarea{color-scheme:dark}.cc-editor input:not([type=radio]):not([type=checkbox]),.cc-editor select,.cc-editor textarea{background:var(--cc-bg)!important;color:var(--cc-text)!important;border-color:var(--cc-line)!important;font-size:13px;max-width:100%}.cc-editor input:disabled,.cc-editor select:disabled{background:var(--cc-soft)!important;opacity:.8}.cc-editor [class~="text-slate-500"],.cc-editor [class~="text-slate-400"]{color:var(--cc-muted)!important}.cc-editor [class~="text-slate-800"]{color:var(--cc-text)!important}.cc-editor [class~="bg-white"]{background:var(--cc-bg)!important}.cc-editor [class~="bg-amber-50"],.cc-editor [class~="bg-amber-100"]{background:var(--cc-warn-bg)!important}.cc-editor [class~="text-amber-800"],.cc-editor [class~="text-amber-700"]{color:var(--cc-warn)!important}.cc-editor [class~="bg-violet-50"]{background:var(--cc-soft)!important}.cc-editor [class~="text-violet-800"],.cc-editor [class~="text-violet-700"]{color:var(--cc-text)!important}.cc-editor [class~="border-violet-200"],.cc-editor [class~="border-amber-200"]{border-color:var(--cc-line)!important}.cc-editor fieldset{margin-top:18px}.cc-editor [hidden],.customer-workspace [hidden]{display:none!important}.cc-savebar{display:flex;justify-content:flex-end;gap:10px;margin-top:20px}.cc-dialog{padding:24px;width:min(94vw,520px);max-height:85vh;overflow:auto;border:1px solid var(--cc-line);border-radius:20px;background:var(--cc-bg);color:var(--cc-text);box-shadow:0 20px 60px #0004}.cc-dialog::backdrop{background:#020617a6}.cc-choice{display:flex;gap:10px;align-items:flex-start;border:1px solid var(--cc-line);padding:14px;border-radius:12px;margin:12px 0;font-size:13px;cursor:pointer}.cc-choice small{display:block;font-size:11px;line-height:1.6;color:var(--cc-muted);margin-top:5px}.cc-choice:has(input:checked){border-color:var(--cc-brand);background:var(--cc-info-bg)}.cc-choice:has(input:disabled){opacity:.5;cursor:not-allowed}.cc-choice input{margin-top:4px;accent-color:#0891b2}.cc-filters{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}.cc-filters label{font-size:11px;color:var(--cc-muted)}.cc-filters select{display:block;width:100%;margin-top:5px;padding:9px 10px;border:1px solid var(--cc-line);border-radius:10px;background:var(--cc-bg);color:var(--cc-text);font-size:12px}.cc-service,.cc-connection{display:inline-flex;align-items:center;gap:4px;white-space:nowrap;padding:3px 7px;border-radius:20px;font-size:9px;line-height:1.5;font-weight:700;background:var(--cc-soft);color:var(--cc-muted);border:1px solid var(--cc-line)}.cc-service[data-status=active],.cc-connection[data-state=online]{background:var(--cc-good-bg);color:var(--cc-good)}.cc-service[data-status=isolated]{background:var(--cc-bad-bg);color:var(--cc-bad)}.cc-connection[data-state=unknown]{background:var(--cc-warn-bg);color:var(--cc-warn)}.cc-row-status{display:flex;flex-direction:column;gap:4px;align-items:flex-end}.cc-router-tag{display:inline-flex;align-items:center;gap:4px;padding:3px 7px;border-radius:6px;font-size:11px;font-weight:700;background:var(--cc-info-bg);color:var(--cc-info)}.cc-router-tag .cc-icon{height:13px;width:13px}.cc-row-note{font-size:10px;color:var(--cc-muted);line-height:1.6}.cc-import-wrap{margin-bottom:16px}@media(max-width:640px){.cc-field-grid{grid-template-columns:1fr}.cc-section{padding:16px}.cc-title{font-size:22px}.cc-head{flex-wrap:wrap}.cc-dialog{padding:18px}.cc-filters{grid-template-columns:1fr 1fr}}
</style>
